    "content": "<Project Sdk=\"Microsoft.NET.Sdk.Razor\">\n\n  <PropertyGroup>\n    <TargetFramework>net10.0</TargetFramework>\n    <Nullable>enable</Nullable>\n    <ImplicitUsings>enable</ImplicitUsings>\n    <RootNamespace>Quorum.Backend.AdminUI</RootNamespace>\n  </PropertyGroup>\n  <PropertyGroup>\n    <!-- Konfiguracja Paczki NuGet Razor Class Library dla Blazor .NET 10 -->\n    <GeneratePackageOnBuild>true</GeneratePackageOnBuild>\n    <PackageId>Quorum.Backend.AdminUI</PackageId>\n    <Version>2.0.0</Version>\n    <Authors>Robert Pieśnikowski</Authors>\n    <Product>Quorum IdentityServer Admin UI (Pure Blazor Radzen)</Product>\n    <Title>Quorum Admin UI - Pure Blazor Radzen for Open.IdentityServer</Title>\n    <Description>Nowoczesny, w 100% oparty o Blazor i Radzen Blazor pakiet RCL (Razor Class Library) dostarczający kompletny panel administracyjny CRUD dla Open.IdentityServer, ASP.NET Identity, OIDC Federations i API Gateway. Architektura oparta o abstrakcyjne interfejsy modeli dziedzinowych z gotową implementacją Entity Framework Core.</Description>\n    <PackageTags>identityserver;openidentityserver;admin;adminui;blazor;radzen;radzen-blazor;oidc;oauth2;dotnet10;rcl</PackageTags>\n    <PackageLicenseExpression>MIT</PackageLicenseExpression>\n    <PackageProjectUrl>https://github.com/rpiesnikowski/Quorum</PackageProjectUrl>\n    <RepositoryUrl>https://github.com/rpiesnikowski/Quorum</RepositoryUrl>\n    <PackageReadmeFile>README.md</PackageReadmeFile>\n    <IncludeSymbols>true</IncludeSymbols>\n    <SymbolPackageFormat>snupkg</SymbolPackageFormat>\n  </PropertyGroup>\n\n  <ItemGroup>\n    <None Include=\"README.md\" Pack=\"true\" PackagePath=\"\\\" />\n  </ItemGroup>\n\n  <ItemGroup>\n    <PackageReference Include=\"Radzen.Blazor\" Version=\"11.2.7\" />\n  </ItemGroup>\n\n  <ItemGroup>\n    <ProjectReference Include=\"..\\Quorum.Backend.EntityFramework\\Quorum.Backend.EntityFramework.csproj\" />\n  </ItemGroup>\n\n</Project>\n"
