    "name": "Quorum.Backend/Components/App.razor",
    "category": "razor",
    "description": "Plik projektu Quorum",
    "content": "@using static Microsoft.AspNetCore.Components.Web.RenderMode\n<!DOCTYPE html>\n<html lang=\"pl\">\n\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <base href=\"/\" />\n    <title>Quorum Backend | IdentityServer & Admin UI</title>\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" />\n    <link rel=\"stylesheet\" href=\"_content/Radzen.Blazor/css/material-base.css\" />\n    <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap\" />\n    <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/icon?family=Material+Icons\" />\n    <style>\n        body {\n            font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n            background-color: #f8fafc;\n            color: #0f172a;\n            margin: 0;\n            padding: 0;\n        }\n        code, pre {\n            font-family: 'JetBrains Mono', monospace;\n        }\n    </style>\n    <HeadOutlet />\n</head>\n\n<body>\n    <Routes @rendermode=\"InteractiveServer\" />\n    <script src=\"@Assets[\"_framework/blazor.web.js\"]\"></script>\n    <script src=\"@Assets[\"_content/Radzen.Blazor/Radzen.Blazor.js\"]\"></script>\n</body>\n\n</html>\n"
