    "content": "<Project Sdk=\"Microsoft.NET.Sdk.Web\">\n\n  <PropertyGroup>\n    <TargetFramework>net10.0</TargetFramework>\n    <Nullable>enable</Nullable>\n    <ImplicitUsings>enable</ImplicitUsings>\n    <RootNamespace>Quorum.Backend</RootNamespace>\n  </PropertyGroup>\n\n  <ItemGroup>\n    <!-- Open.IdentityServer (Rock Solid Knowledge) -->\n    <PackageReference Include=\"Open.IdentityServer\" Version=\"2.0.0\" />\n    <PackageReference Include=\"Open.IdentityServer.AspNetIdentity\" Version=\"2.0.0\" />\n    <PackageReference Include=\"Open.IdentityServer.EntityFramework\" Version=\"2.0.0\" />\n\n    <!-- ASP.NET Core Identity & EF Core -->\n    <PackageReference Include=\"Microsoft.AspNetCore.Identity.EntityFrameworkCore\" Version=\"10.0.10\" />\n    <PackageReference Include=\"Microsoft.EntityFrameworkCore\" Version=\"10.0.10\" />\n    <PackageReference Include=\"Microsoft.EntityFrameworkCore.Relational\" Version=\"10.0.10\" />\n    <PackageReference Include=\"Microsoft.EntityFrameworkCore.Design\" Version=\"10.0.10\">\n      <PrivateAssets>all</PrivateAssets>\n      <IncludeAssets>runtime; build; native; contentfiles; analyzers; buildtransitive</IncludeAssets>\n    </PackageReference>\n  </ItemGroup>\n  <ItemGroup>\n    <PackageReference Include=\"Radzen.Blazor\" Version=\"11.2.7\" />\n    <PackageReference Include=\"Microsoft.AspNetCore.SignalR.StackExchangeRedis\" Version=\"10.0.10\" />\n  </ItemGroup>\n  <ItemGroup>\n    <!-- Referencje do projektów wewnętrznych Quorum -->\n    <ProjectReference Include=\"..\\Quorum.Backend.AdminAPI\\Quorum.Backend.AdminAPI.csproj\" />\n    <ProjectReference Include=\"..\\Quorum.Backend.AdminUI\\Quorum.Backend.AdminUI.csproj\" />\n    <ProjectReference Include=\"..\\Quorum.Backend.EntityFramework\\Quorum.Backend.EntityFramework.csproj\" />\n    <ProjectReference Include=\"..\\Quorum.ServiceDefaults\\Quorum.ServiceDefaults.csproj\" />\n  </ItemGroup>\n\n</Project>\n"
